def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    result = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            top = stack.pop()
            if top == '(':
                result.append('()')
            else:
                result[-1] += ')'

    while stack:
        result.append('()')
        stack.pop()

    return result

