def preorder_traversal(inorder: str, postorder: str) -> str:
    # Initialize an empty stack
    stack = []

    # Iterate through the postorder traversal
    for i in range(len(postorder)):
        # If the current character is not in the inorder traversal,
        # it must be a left child of the current node
        if postorder[i] not in inorder:
            # Push the current character onto the stack
            stack.append(postorder[i])

    # Iterate through the inorder traversal
    for i in range(len(inorder)):
        # If the current character is not in the postorder traversal,
        # it must be a right child of the current node
